mapper.select:
WITH requested ( step_id, channel_id, recipient_group_id, template_id, recovery_template_id ) AS ( VALUES
( CAST(#{step.id} AS UUID), CAST(#{step.channelId} AS UUID), CAST(#{step.recipientGroupId} AS UUID), CAST(#{step.templateId} AS UUID), CAST(#{step.recoveryTemplateId} AS UUID) )
) SELECT requested.step_id AS stepId, channel.status AS channelStatus, channel.channel_type AS channelType, recipient_group.status AS recipientGroupStatus, ( SELECT COUNT(*) FROM notification_recipient recipient WHERE recipient.group_id = requested.recipient_group_id AND recipient.channel_type = channel.channel_type AND recipient.status = 'ENABLED' ) AS enabledRecipientCount, trigger_template.status AS templateStatus, trigger_template.channel_type AS templateChannelType, trigger_template.event_type AS templateEventType, recovery_template.status AS recoveryTemplateStatus, recovery_template.channel_type AS recoveryTemplateChannelType, recovery_template.event_type AS recoveryTemplateEventType FROM requested LEFT JOIN notification_channel channel ON channel.id = requested.channel_id LEFT JOIN notification_recipient_group recipient_group ON recipient_group.id = requested.recipient_group_id LEFT JOIN notification_template trigger_template ON trigger_template.id = requested.template_id LEFT JOIN notification_template recovery_template ON recovery_template.id = requested.recovery_template_id ORDER BY requested.step_id
